import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.DA69LXMH.js";const g=JSON.parse('{"title":"Requisitos do Sistema","description":"","frontmatter":{},"headers":[],"relativePath":"guia/requisitos.md","filePath":"guia/requisitos.md"}'),s={name:"guia/requisitos.md"};function t(n,o,d,c,l,u){return a(),r("div",null,[...o[0]||(o[0]=[i('<h1 id="requisitos-do-sistema" tabindex="-1">Requisitos do Sistema <a class="header-anchor" href="#requisitos-do-sistema" aria-label="Permalink to &quot;Requisitos do Sistema&quot;">​</a></h1><p>Antes de baixar e instalar o <strong>EchoBot</strong>, verifique se o seu computador atende às especificações necessárias para o modo de operação desejado (Aceleração por GPU NVIDIA ou Modo Leve em CPU).</p><hr><h2 id="💻-requisitos-de-hardware" tabindex="-1">💻 Requisitos de Hardware <a class="header-anchor" href="#💻-requisitos-de-hardware" aria-label="Permalink to &quot;💻 Requisitos de Hardware&quot;">​</a></h2><h3 id="configuracao-recomendada-aceleracao-por-gpu-nvidia-cuda" tabindex="-1">Configuração Recomendada (Aceleração por GPU NVIDIA CUDA) <a class="header-anchor" href="#configuracao-recomendada-aceleracao-por-gpu-nvidia-cuda" aria-label="Permalink to &quot;Configuração Recomendada (Aceleração por GPU NVIDIA CUDA)&quot;">​</a></h3><p>Ideal para transcrição ultrarrápida com o modelo <strong>Whisper Large-v3-Turbo</strong>, identificação biométrica de oradores em segundos e narração em alta fidelidade:</p><ul><li><strong>Sistema Operacional:</strong> Windows 10 ou 11 (64-bit) ou Linux (Ubuntu 22.04+ / Docker)</li><li><strong>Placa de Vídeo (GPU):</strong> NVIDIA GeForce com arquitetura Turing ou superior (GTX 1660, RTX 2060, RTX 3060, RTX 4060 ou superior) com no mínimo <strong>6 GB de VRAM</strong>.</li><li><strong>Driver Gráfico:</strong> Driver NVIDIA atualizado (com suporte a CUDA 12.x).</li><li><strong>Processador (CPU):</strong> Intel Core i5/i7 (9ª geração+) ou AMD Ryzen 5/7 (3000 series+).</li><li><strong>Memória RAM:</strong> 16 GB DDR4/DDR5.</li><li><strong>Armazenamento:</strong> 10 GB de espaço livre em disco SSD (NVMe recomendado para carregamento instantâneo de modelos).</li></ul><h3 id="configuracao-minima-modo-cpu-whisper-tiny-base" tabindex="-1">Configuração Mínima (Modo CPU / Whisper Tiny-Base) <a class="header-anchor" href="#configuracao-minima-modo-cpu-whisper-tiny-base" aria-label="Permalink to &quot;Configuração Mínima (Modo CPU / Whisper Tiny-Base)&quot;">​</a></h3><p>Projetada para notebooks e computadores sem placa de vídeo dedicada:</p><ul><li><strong>Sistema Operacional:</strong> Windows 10 ou 11 (64-bit).</li><li><strong>Processador (CPU):</strong> Intel Core i5 (8ª geração+) ou AMD Ryzen 5 2600+ (mínimo 4 núcleos / 8 threads).</li><li><strong>Memória RAM:</strong> 8 GB.</li><li><strong>Armazenamento:</strong> 5 GB de espaço livre em disco (SSD recomendado).</li><li><strong>Modelos Suportados em CPU:</strong> <code>tiny</code>, <code>base</code> ou processamento via provedores em nuvem.</li></ul><hr><h2 id="🌐-conectividade-e-portas-de-rede" tabindex="-1">🌐 Conectividade e Portas de Rede <a class="header-anchor" href="#🌐-conectividade-e-portas-de-rede" aria-label="Permalink to &quot;🌐 Conectividade e Portas de Rede&quot;">​</a></h2><ul><li><strong>Operação 100% Offline (Local):</strong> Quando configurado com os modelos locais de Speech-to-Text (<strong>Faster-Whisper</strong>) e Text-to-Speech (<strong>Kokoro Local ONNX</strong>), o EchoBot funciona inteiramente sem conexão com a internet.</li><li><strong>Provedores de IA em Nuvem (Opcional):</strong> Caso prefira utilizar APIs externas como <strong>Google Gemini</strong>, <strong>OpenAI GPT-4o</strong>, <strong>Claude 3.5</strong>, <strong>Groq</strong>, <strong>OpenRouter</strong>, <strong>ElevenLabs</strong> ou <strong>Deepgram</strong>, é necessária uma conexão de banda larga ativa para envio de prompts e streaming de áudio.</li><li><strong>Portas Utilizadas na Máquina Local:</strong><ul><li><strong>Porta <code>8000</code>:</strong> Servidor principal FastAPI e aplicação web frontend do Mestre.</li><li><strong>Porta <code>8001</code>:</strong> Whisper Sidecar dedicado para isolamento de memória de IA.</li></ul></li><li><strong>Firewall do Windows:</strong> Durante a primeira execução, autorize a comunicação em redes privadas para permitir a troca de mensagens com o bot do Discord e a conexão do túnel do Portal do Jogador.</li></ul>',13)])])}const p=e(s,[["render",t]]);export{g as __pageData,p as default};
